CREATE OR REPLACE FUNCTION transfer(p_from int, p_to int, p_amount numeric)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  -- Lock both rows in a fixed order (lowest id first)
  PERFORM 1
     FROM accounts
    WHERE account_id IN (p_from, p_to)
    ORDER BY account_id
      FOR UPDATE;

  UPDATE accounts SET balance = balance - p_amount WHERE account_id = p_from;
  UPDATE accounts SET balance = balance + p_amount WHERE account_id = p_to;
END;
$$;

SELECT transfer(3, 1, 150);
SELECT * FROM accounts ORDER BY account_id;

